def family_init(ctx):
    """Locate each session's closing bar, then read the post-15:50 reaction."""
    bars = ctx.bars
    m = len(bars)
    c = [float(b["c"]) for b in bars]
    v = [float(b.get("v") or 0.0) for b in bars]
    t = [b["t"] for b in bars]
    mind = [0] * m
    day = [""] * m
    for i in range(m):
        s = t[i]
        day[i] = s[:10]
        try:
            mind[i] = int(s[11:13]) * 60 + int(s[14:16])
        except Exception:
            mind[i] = 0

    days = []
    idx = {}
    for i in range(m):
        d = day[i]
        if not days or days[-1] != d:
            days.append(d)
            idx[d] = []
        idx[d].append(i)

    # the regular open: per session the heaviest bar of its first half, then
    # the modal minute across sessions. Robust to DST and to odd sessions.
    votes = {}
    for d in days:
        js = idx[d]
        half = js[:max(1, len(js) // 2)]
        oi = half[0]
        for j in half:
            if v[j] > v[oi]:
                oi = j
        votes[mind[oi]] = votes.get(mind[oi], 0) + 1
    om = 0
    best = -1
    for k in sorted(votes):
        if votes[k] > best:
            best = votes[k]
            om = k
    span = max(30, int(ctx.p.rth_minutes))
    minbars = max(5, int(ctx.p.min_bars_day))

    close_i = {}
    for d in days:
        cand = [j for j in idx[d] if om <= mind[j] < om + span]
        if len(cand) >= minbars:
            close_i[d] = cand[-1]

    flat = [False] * m
    for d in days:
        ci = close_i.get(d)
        if ci is None:
            for j in idx[d]:
                flat[j] = True
        else:
            for j in idx[d]:
                if j >= ci:
                    flat[j] = True
    ctx._flat = flat

    sig = [0] * m
    off = max(1, int(ctx.p.sig_off))
    ref = max(1, int(ctx.p.ref))
    q = float(ctx.p.pctl) / 100.0
    if q < 0.05:
        q = 0.05
    if q > 0.95:
        q = 0.95
    dlook = max(5, int(ctx.p.dlook))
    vlook = max(5, int(ctx.p.vlook))
    minh = max(3, int(ctx.p.min_hist))
    vmult = float(ctx.p.vmult)

    dhist = []
    vhist = []
    for d in days:
        ci = close_i.get(d)
        if ci is None:
            continue
        s = ci - off
        p1 = s - ref
        if p1 < 0 or day[p1] != d or day[s] != d:
            continue
        if c[p1] <= 0.0:
            continue
        mv = c[s] / c[p1] - 1.0
        vs = 0.0
        for j in range(s - ref + 1, s + 1):
            if j >= 0 and day[j] == d:
                vs += v[j]
        if len(dhist) >= minh and len(vhist) >= minh:
            w = sorted(dhist[-dlook:])
            L = len(w)
            k = int(q * L)
            if k >= L:
                k = L - 1
            thr = w[k]
            vw = sorted(vhist[-vlook:])
            vmed = vw[len(vw) // 2]
            if abs(mv) > thr and vmed > 0.0 and vs > vmult * vmed:
                sig[s] = 1 if mv > 0.0 else -1
        dhist.append(abs(mv))
        vhist.append(vs)
    ctx._sig = sig


def signal(ctx, i):
    s = ctx._sig[i]
    return int(s) if s else 0


def exit_signal(ctx, i):
    return bool(ctx._flat[i])
